def seed_cards(apps, schema_editor):
    Card = apps.get_model("core", "DiscoverCard")
    for i, (key, typ, icon, route, url, tbn, ten, dbn, den) in enumerate(SEED):
        Card.objects.get_or_create(key=key, defaults=dict(
            type=typ, icon=icon, route=route, url=url, title_bn=tbn,
            title_en=ten, desc_bn=dbn, desc_en=den, order=(i + 1) * 10,
            enabled=True, audience="all"))


def unseed_cards(apps, schema_editor):
    apps.get_model("core", "DiscoverCard").objects.filter(
        key__in=[s[0] for s in SEED]).delete()


